make_plot_data <- function(n_versions, scenario, lambda_vector, proba_TEA_0, proba_TEA_0.5, proba_TEA_1, proba_TEA_EB_0.5, proba_TEA_EB_1, proba_TEA_EB_epsilon) { data.frame( lambda = rep(lambda_vector, 6), probability = c( proba_TEA_0, proba_TEA_0.5, proba_TEA_1, proba_TEA_EB_0.5, proba_TEA_EB_1, proba_TEA_EB_epsilon ), method = rep(c( "ε = 0 (no borrowing)", "ε = 0.5 without EB", "ε = 1 without EB (full borrowing)", "ε = 0.5 with EB", "ε = 1 with EB", "Liang (2023) EB approach" ), each = length(lambda_vector)), n_versions = n_versions, scenario = scenario ) }


